use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn analyze_dependencies (output_dir : & PathBuf) -> Result < DependencyAnalysis > { let mut analysis = DependencyAnalysis { total_crates : 0 , dependency_conflicts : Vec :: new () , dependency_types : HashMap :: new () , } ; let mut global_deps : HashMap < String , Vec < (String , String) > > = HashMap :: new () ; for entry in WalkDir :: new (output_dir) . max_depth (1) { let entry = entry ? ; let path = entry . path () ; if path . is_dir () && path . file_name () . and_then (| n | n . to_str ()) . map (| s | s . starts_with ("wrapped-")) . unwrap_or (false) { let crate_name = path . file_name () . unwrap () . to_str () . unwrap () ; let cargo_toml_path = path . join ("Cargo.toml") ; if cargo_toml_path . exists () { analysis . total_crates += 1 ; analyze_crate_dependencies (& cargo_toml_path , crate_name , & mut analysis , & mut global_deps) ? ; } } } for (dep_name , specs) in global_deps { if specs . len () > 1 { let unique_specs : HashSet < String > = specs . iter () . map (| (_ , spec) | spec . clone ()) . collect () ; if unique_specs . len () > 1 { let mut conflict_details = Vec :: new () ; for (crate_name , spec) in & specs { conflict_details . push (format ! ("{}: {}" , crate_name , spec)) ; } analysis . dependency_conflicts . push (ConflictReport { crate_name : "multiple" . to_string () , dependency_name : dep_name , conflict_details , }) ; } } } Ok (analysis) }
}